import { MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, vec3, vec4, mix, smoothstep } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry } = ctx.THREE;

  // Root container
  const root = new Group();

  // 1. Stage / Card Backing (Engineered Gradient Panel)
  // Standard aspect ratio for the card mapping to 512x320 source rect (1.6:1)
  const cardW = 2.4;
  const cardH = 1.5;
  const geom = new PlaneGeometry(cardW, cardH);

  const mat = new MeshBasicNodeMaterial({
    transparent: true,
    depthWrite: false
  });

  // Engineered gradient surface: Transition from near-black surface to deep ink
  // with a subtle precision accent border highlight
  const uVS = uv();
  const cSurface = vec3(0.043, 0.043, 0.062); // #0b0b10
  const cInk = vec3(0.086, 0.086, 0.114);     // #16161d
  const cAccent = vec3(1.0, 0.165, 0.22);      // #ff2a38

  // Base vertical gradient
  const baseGrad = mix(cSurface, cInk, uVS.y);

  // Precision border math
  const borderX = smoothstep(0.0, 0.015, uVS.x).mul(smoothstep(0.0, 0.015, uVS.x.oneMinus()));
  const borderY = smoothstep(0.0, 0.024, uVS.y).mul(smoothstep(0.0, 0.024, uVS.y.oneMinus()));
  const borderMask = borderX.mul(borderY).oneMinus();

  // Final composite color
  const finalColor = mix(baseGrad, cAccent, borderMask.mul(0.35));
  mat.colorNode = vec4(finalColor, 0.95);

  const panel = new Mesh(geom, mat);
  root.add(panel);

  // 2. Texture Layer (Isolated Hero Overlay)
  const imgGeom = new PlaneGeometry(cardW * 0.9, cardH * 0.9);
  const imgMat = new MeshBasicNodeMaterial({
    transparent: true,
    depthWrite: false,
    opacity: 0.05 // Soft industrial watermark layout
  });
  const imgMesh = new Mesh(imgGeom, imgMat);
  imgMesh.position.set(0, 0, 0.002);
  root.add(imgMesh);

  const targetImg = config.imageUrl || '/prism-mock/home/nodes/cta-hero-isolated.png';
  ctx.textureLoader.loadTexture(targetImg).then((texture) => {
    imgMat.colorNode = texture;
    imgMat.opacity = 0.55; // Fade-in texture weight beautifully once loaded
    imgMat.needsUpdate = true;
  }).catch(() => {});

  // 3. Typographic Header Hierarchy
  // "Pricing 3" Headline
  const textStr = "Pricing 3";
  const titleText = ctx.fontAtlas.createText(textStr, {
    fontSize: 39,
    color: '#e8ecf2', // Crisp paper white
    align: 'center'
  });
  // Center-aligned offset positioning inside the card frame
  titleText.position.set(0, -0.05, 0.01);
  root.add(titleText);

  // Intro Transition (rise-in with GSAP)
  const tl = gsap.timeline();
  tl.fromTo(root.position, 
    { y: '-=0.2', x: '+=0' }, 
    { y: '+=0.2', duration: 0.8, ease: 'power3.out' }
  );
  tl.fromTo(root.scale,
    { x: 0.96, y: 0.96, z: 0.96 },
    { x: 1, y: 1, z: 1, duration: 0.9, ease: 'power4.out' },
    '-=0.8'
  );

  // Clean-up Interface
  root.userData = {
    handlers: {},
    cleanup() {
      if (tl) tl.kill();
      geom.dispose();
      imgGeom.dispose();
      mat.dispose();
      imgMat.dispose();
    }
  };

  return root;
}
